#include <iostream>
#include <sstream>
#include <string>

std::string componer_resumen(int validos, int rechazados) {
    std::ostringstream texto;
    texto << "Valid=" << validos << ";Rejected=" << rechazados;
    return texto.str();
}

int main() {
    std::string primero = componer_resumen(2, 1);
    std::string segundo = componer_resumen(0, 0);
    std::cout << primero << "\n" << segundo;
    return 0;
}

#include <fstream>
#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::ostringstream texto;
    texto << "Valid=" << 2 << ";Rejected=" << 1;
    std::string mensaje = texto.str();
    std::ofstream salida{"resumen_lgp.txt"};
    if (!salida) {
        std::cout << "Open error";
        return 1;
    }
    salida << mensaje;
    salida.close();
    if (!salida) {
        std::cout << "Write error";
        return 1;
    }
    std::cout << "Saved";
    return 0;
}
